def minimum_operations(s1: str, s2: str, s3: str) -> int:
    """Return the fewest allowed deletions needed to make all three strings equal."""
    common_length = 0

    for a, b, c in zip(s1, s2, s3):
        if a != b or b != c:
            break
        common_length += 1

    if common_length == 0:
        return -1

    return len(s1) + len(s2) + len(s3) - 3 * common_length
