    if not data:
        return

    n, h, w = data[:3]
    tiles = [
        tuple(sorted((data[3 + 2 * i], data[4 + 2 * i])))
        for i in range(n)
    ]

    full = (1 << (h * w)) - 1

    @lru_cache(None)
    def can_place(occupied, used):
        if occupied == full:
            return True

        free_cells = h * w - occupied.bit_count()
        remaining_areas = [
            tiles[i][0] * tiles[i][1]
            for i in range(n)
            if not (used >> i) & 1
        ]

        # The free area must equal the area of some subset of unused tiles.
        possible_areas = {0}
