def max_prime_distance(nums):
    """
    Returns the maximum distance between indices of prime numbers in the given list.
    Since at least one prime exists, the answer is the difference between the last
    and first prime indices.
    """
    def is_prime(n):
        if n < 2:
            return False
        for i in range(2, int(n ** 0.5) + 1):
            if n % i == 0:
                return False
        return True

    first_prime_index = None
    last_prime_index = None

    for i, num in enumerate(nums):
        if is_prime(num):
            if first_prime_index is None:
                first_prime_index = i
            last_prime_index = i

    return last_prime_index - first_prime_index
