def medianOfUniquenessArray(nums: list[int]) -> int:
    """Return the lower median of distinct-element counts over all subarrays."""
    n = len(nums)
    total_subarrays = n * (n + 1) // 2
    target = (total_subarrays + 1) // 2

    def count_at_most(k: int) -> int:
        frequencies = {}
        left = 0
        count = 0

        for right, value in enumerate(nums):
            frequencies[value] = frequencies.get(value, 0) + 1

            while len(frequencies) > k:
                left_value = nums[left]
                frequencies[left_value] -= 1
                if frequencies[left_value] == 0:
                    del frequencies[left_value]
                left += 1

            count += right - left + 1

        return count

    low, high = 1, min(n, len(set(nums)))
    while low < high:
        mid = (low + high) // 2
        if count_at_most(mid) >= target:
            high = mid
        else:
            low = mid + 1

    return low
